import { test, expect } from 'vitest';
import { applyCoupon } from './coupon.js';

test('SAVE10 takes 10% off', async () => {
  await expect(applyCoupon(200, 'SAVE10')).resolves.toBe(180);
});

test('codes are case-insensitive', async () => {
  await expect(applyCoupon(200, 'save10')).resolves.toBe(180);
});

test('unknown codes are rejected', async () => {
  await expect(applyCoupon(200, 'NOPE')).rejects.toThrow('Unknown coupon');
});

test('expired codes are rejected', async () => {
  await expect(applyCoupon(200, 'OLD5')).rejects.toThrow('Coupon expired');
});

